// A. Mock-up = horizontal (screens, no depth); proof of concept = vertical (one slice, real technology).
const PROTOTYPES = {
  S1: 'PROOF_OF_CONCEPT',
  S2: 'PAPER',
  S3: 'EVOLUTIONARY',
  S4: 'THROWAWAY',
  S5: 'ELECTRONIC',
  S6: 'MOCK_UP',
};

// D. Wiegers Ch.15: risks and success factors of prototyping.
const PROTOTYPING_TRUTHS = {
  R1: 'TRUE',
  R2: 'FALSE',
  R3: 'TRUE',
  R4: 'FALSE',
  R5: 'TRUE',
  R6: 'TRUE',
};

// E. Nouns that have their own identity and behaviour ⇒ classes; nouns that describe them ⇒ attributes; verbs ⇒ operations.
const DESIGN_CANDIDATES = {
  W1: 'CLASS',
  W2: 'CLASS',
  W3: 'CLASS',
  W4: 'CLASS',
  W5: 'ATTRIBUTE',
  W6: 'ATTRIBUTE',
  W7: 'ATTRIBUTE',
  W8: 'OPERATION',
  W9: 'OPERATION',
};

